#!/usr/bin/env python3
"""Turn the shot stills into clips.

Two kinds of clip come out of this:

  * a real image-to-video clip, generated by an actual video model, for
    the shots where movement is the whole point (the cat walking, the
    nuzzle, the hand on the head)
  * a camera move over a still, for the shots that can carry themselves
    on framing alone

The split matters because video models are expensive and rate limited.
The plan marks which shots need real motion with ``"ltx": true``, and
those get the budget first.

Usage:
    python make_clips.py --plan shots.json --stills shots_clean --out clips
    python make_clips.py --plan shots.json --stills shots_clean --out clips --only s04
    python make_clips.py --plan shots.json --stills shots_clean --out clips --no-ltx
"""

from __future__ import annotations

import argparse
import json
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
SCRIPTS = Path.home() / ".workbuddy" / "skills" / "video-mix" / "scripts"

sys.path.insert(0, str(SCRIPTS))
from vmix_common import ffmpeg_bin  # noqa: E402

WIDTH, HEIGHT, FPS = 1080, 1920, 30
# The video model works at a smaller size; the rest is scaled up during
# assembly.
VIDEO_W, VIDEO_H = 576, 1024


def run(cmd: list[str], label: str) -> bool:
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        print(f"[clip] {label} FAILED")
        print((r.stderr or r.stdout)[-900:], file=sys.stderr)
        return False
    return True


def make_ltx(still: Path, prompt: str, dst: Path, seconds: float,
             width: int, height: int) -> bool:
    """A real image-to-video clip."""
    cmd = [sys.executable, str(SCRIPTS / "gen_video.py"),
           "--image", str(still), "--prompt", prompt,
           "--out", str(dst), "--duration", "2",
           "--width", str(width), "--height", str(height),
           "--backend", "ltx"]
    return run(cmd, f"ltx {dst.name}")


def make_move(still: Path, dst: Path, motion: str, seconds: float) -> bool:
    """A camera move over the still."""
    cmd = [sys.executable, str(HERE / "camera_move.py"),
           "--image", str(still), "--out", str(dst),
           "--motion", motion, "--seconds", f"{seconds:.2f}",
           "--width", str(WIDTH), "--height", str(HEIGHT),
           "--fps", str(FPS)]
    return run(cmd, f"{motion} {dst.name}")


def main() -> int:
    ap = argparse.ArgumentParser(description="Make the clips")
    ap.add_argument("--plan", required=True)
    ap.add_argument("--stills", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--only", nargs="*")
    ap.add_argument("--no-ltx", action="store_true",
                    help="skip the video model, camera moves only")
    args = ap.parse_args()

    plan = json.loads(Path(args.plan).read_text("utf-8"))
    stills = Path(args.stills)
    outdir = Path(args.out)
    outdir.mkdir(parents=True, exist_ok=True)

    for shot in plan["shots"]:
        sid = shot["id"]
        if args.only and sid not in args.only:
            continue
        still = stills / f"{sid}.jpg"
        if not still.exists():
            print(f"[clip] missing still {still}", file=sys.stderr)
            continue
        dst = outdir / f"{sid}.mp4"
        if dst.exists() and dst.stat().st_size > 20000:
            print(f"[clip] skip {dst.name} (exists)")
            continue

        want_ltx = shot.get("ltx") and not args.no_ltx
        ok = False
        if want_ltx:
            print(f"[clip] {sid}: image-to-video (real motion)")
            ok = make_ltx(still, shot.get("ltx_prompt", shot.get("action", "")),
                          dst, shot["duration"], VIDEO_W, VIDEO_H)
        if not ok:
            print(f"[clip] {sid}: camera move ({shot.get('motion', 'push-in')})")
            ok = make_move(still, dst, shot.get("motion", "push-in"),
                           shot["duration"])
        if ok:
            print(f"[clip]    ok {dst.name} "
                  f"({dst.stat().st_size // 1024} KB)")
        else:
            print(f"[clip]    {sid} could not be produced", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
